package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevDept string // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var EmpRecG EmpRec

// file handling for EMP-FILE
var empLines []string
var empIdx int

func initVars() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = "   "
	WsRegHours = decimal.New(0, 0)
	WsOtHours = decimal.New(0, 0)
	WsGross = decimal.New(0, 0)
	WsDeptTotal = decimal.New(0, 0)
	WsDeptCount = 0
	WsGrandTotal = decimal.New(0, 0)
	WsGrandCount = 0
}

func formatEdited(v decimal.Decimal, picture string) string {
	// split picture
	dotPos := strings.Index(picture, ".")
	var picInt, picDec string
	if dotPos >= 0 {
		picInt = picture[:dotPos]
		picDec = picture[dotPos+1:]
	} else {
		picInt = picture
		picDec = ""
	}
	intDigits := 0
	for _, c := range picInt {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, c := range picDec {
		if c == 'Z' || c == '9' {
			decDigits++
		}
	}
	// Build scaled integer string
	av := v.Abs()
	// scale to decDigits
	scaled := av.Shift(int32(decDigits)).Truncate(0)
	scaledStr := scaled.StringFixed(0) // integer, may be "0"
	// scaledStr should represent intPart*10^decDigits+frac
	// Remove sign if any (Abs already)
	// Handle high-order overflow: integer part length
	// integer part length in scaledStr = len - decDigits (if scaledStr length > decDigits)
	// But when scaledStr has less digits than decDigits+1, we need padding later.
	// For overflow detection we need intDigits limit.
	// Determine if integer part exceeds intDigits
	if decDigits > 0 {
		// ensure scaledStr has at least decDigits+1 chars for int part logic?
		// overflow case:
		if len(scaledStr) > intDigits+decDigits {
			// keep low intDigits of integer part + decDigits fraction
			// integer part = scaledStr[0:len-decDigits]
			intPart := scaledStr[:len(scaledStr)-decDigits]
			fracPart := scaledStr[len(scaledStr)-decDigits:]
			if len(intPart) > intDigits {
				intPart = intPart[len(intPart)-intDigits:]
			}
			// pad intPart to intDigits if needed (when intPart shorter?)
			if len(intPart) < intDigits {
				intPart = strings.Repeat("0", intDigits-len(intPart)) + intPart
			}
			scaledStr = intPart + fracPart
		} else {
			// pad left zeros to intDigits+decDigits
			need := intDigits + decDigits
			if len(scaledStr) < need {
				scaledStr = strings.Repeat("0", need-len(scaledStr)) + scaledStr
			}
		}
	} else {
		if len(scaledStr) > intDigits {
			scaledStr = scaledStr[len(scaledStr)-intDigits:]
		} else if len(scaledStr) < intDigits {
			scaledStr = strings.Repeat("0", intDigits-len(scaledStr)) + scaledStr
		}
	}
	// Now split into intFormatted and decFormatted
	var intFormatted, decFormatted string
	if decDigits > 0 {
		// scaledStr length should be intDigits+decDigits now
		if len(scaledStr) < intDigits+decDigits {
			scaledStr = strings.Repeat("0", intDigits+decDigits-len(scaledStr)) + scaledStr
		}
		intFormatted = scaledStr[:len(scaledStr)-decDigits]
		decFormatted = scaledStr[len(scaledStr)-decDigits:]
		// ensure lengths
		if len(intFormatted) < intDigits {
			intFormatted = strings.Repeat("0", intDigits-len(intFormatted)) + intFormatted
		}
		if len(intFormatted) > intDigits {
			intFormatted = intFormatted[len(intFormatted)-intDigits:]
		}
		if len(decFormatted) < decDigits {
			decFormatted = decFormatted + strings.Repeat("0", decDigits-len(decFormatted))
		}
	} else {
		intFormatted = scaledStr
		if len(intFormatted) < intDigits {
			intFormatted = strings.Repeat("0", intDigits-len(intFormatted)) + intFormatted
		}
		if len(intFormatted) > intDigits {
			intFormatted = intFormatted[len(intFormatted)-intDigits:]
		}
	}

	// Build int section output
	outInt := make([]byte, len(picInt))
	di := 0
	suppress := true
	for pi := 0; pi < len(picInt); pi++ {
		c := picInt[pi]
		if c == ',' {
			if suppress {
				outInt[pi] = ' '
			} else {
				outInt[pi] = ','
			}
		} else if c == 'Z' || c == '9' {
			d := intFormatted[di]
			di++
			if suppress && d == '0' && c == 'Z' {
				outInt[pi] = ' '
			} else {
				outInt[pi] = d
				suppress = false
			}
		} else {
			outInt[pi] = byte(c)
		}
	}
	if dotPos >= 0 {
		// build dec section
		outDec := make([]byte, len(picDec))
		for i := 0; i < len(picDec); i++ {
			c := picDec[i]
			if c == 'Z' || c == '9' {
				// consume decFormatted in order
				// decFormatted index corresponds to position of Z/9 in picDec
				// count Z/9 before i
				cnt := 0
				for k := 0; k < i; k++ {
					if picDec[k] == 'Z' || picDec[k] == '9' {
						cnt++
					}
				}
				if cnt < len(decFormatted) {
					outDec[i] = decFormatted[cnt]
				} else {
					outDec[i] = '0'
				}
			} else {
				outDec[i] = byte(c)
			}
		}
		return string(outInt) + "." + string(outDec)
	}
	return string(outInt)
}

func pow10Dec(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func storeDecimal(val decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	// truncate toward zero to scale
	v := val.Truncate(scale)
	if intDigits <= 0 {
		return v
	}
	pow := pow10Dec(intDigits)
	// high order drop: keep remainder modulo pow, preserve sign
	if v.Abs().Cmp(pow) >= 0 {
		// use Mod
		rem := v.Mod(pow)
		// Mod keeps sign of dividend in this library? Ensure same sign as v
		return rem
	}
	return v
}

func formatPIC9(n int64, digits int) string {
	// keep low order digits
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if digits < 19 {
		n = n % mod
		if n < 0 {
			n += mod
		}
	}
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, n)
}

func openEmpFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		if os.IsNotExist(err) {
			empLines = []string{}
			empIdx = 0
			return
		}
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	// Use bufio to preserve handling but simple split
	// We need to split on lines, keeping content without newline.
	// Use scanner-like split to handle \r\n
	content := string(data)
	// Normalize \r\n -> \n
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		empLines = []string{}
	} else {
		parts := strings.Split(content, "\n")
		// If file ends with newline, last part is empty after split -> should not be a record
		// COBOL LINE SEQUENTIAL: last newline does not create extra record.
		// So remove trailing empty element if original ends with \n
		if len(parts) > 0 && strings.HasSuffix(content, "\n") {
			// last element is after trailing newline, drop it
			parts = parts[:len(parts)-1]
		}
		empLines = parts
	}
	empIdx = 0
}

func parseEmpLine(line string) EmpRec {
	// pad to 17 with spaces
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	erId := line[0:5]
	erDept := line[5:8]
	sHours := line[8:12]
	sRate := line[12:17]
	var hDec decimal.Decimal
	var rDec decimal.Decimal
	// hours: 4 digits implied 1 decimal
	hs := strings.TrimSpace(sHours)
	if hs == "" {
		hs = "0"
	}
	// sHours may contain spaces due to padding; if so parse as 0? But assume digits
	// Remove spaces
	hs = strings.TrimSpace(hs)
	if hs == "" {
		hDec = decimal.New(0, 0)
	} else {
		// hs should be digits, may have leading zeros
		// parse as int
		var iv int64
		fmt.Sscanf(hs, "%d", &iv)
		// But sHours is exactly 4 chars digits; better parse digits only
		// If hs contains non-digit, Sscanf may fail; fallback
		// Use manual
		iv = 0
		for _, ch := range hs {
			if ch >= '0' && ch <= '9' {
				iv = iv*10 + int64(ch-'0')
			}
		}
		hDec = decimal.New(iv, -1)
	}
	rs := strings.TrimSpace(sRate)
	if rs == "" {
		rs = "0"
	}
	rs = strings.TrimSpace(rs)
	if rs == "" {
		rDec = decimal.New(0, 0)
	} else {
		iv := int64(0)
		for _, ch := range rs {
			if ch >= '0' && ch <= '9' {
				iv = iv*10 + int64(ch-'0')
			}
		}
		rDec = decimal.New(iv, -2)
	}
	return EmpRec{ErId: erId, ErDept: erDept, ErHours: hDec, ErRate: rDec}
}

// paragraph functions

func MAIN_PARA() {
	OPEN_INPUT_EMP_FILE()
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	if !FIRST_RECORD() {
		DEPT_BREAK_PARA()
	}
	CLOSE_EMP_FILE()
	GRAND_PARA()
}

func OPEN_INPUT_EMP_FILE() {
	openEmpFile()
}
func CLOSE_EMP_FILE() {}

func READ_PARA() {
	if empIdx >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIdx]
	empIdx++
	EmpRecG = parseEmpLine(line)
}

func INPUT_DONE() bool { return WsEofFlag == "Y" }
func FIRST_RECORD() bool { return WsFirstFlag == "Y" }

func PROCESS_PARA() {
	if FIRST_RECORD() {
		WsPrevDept = EmpRecG.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecG.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecG.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	forty := decimal.NewFromInt(40)
	if EmpRecG.ErHours.Cmp(forty) > 0 {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = EmpRecG.ErHours.Sub(forty)
		// store truncation to scale 1 and intDigits 3
		WsOtHours = storeDecimal(WsOtHours, 1, 3)
		WsRegHours = storeDecimal(WsRegHours, 1, 3)
	} else {
		WsRegHours = EmpRecG.ErHours
		WsRegHours = storeDecimal(WsRegHours, 1, 3)
		WsOtHours = decimal.New(0, 0)
		WsOtHours = storeDecimal(WsOtHours, 1, 3)
	}
	onePointFive := decimal.New(15, -1) // 1.5
	grossCalc := WsRegHours.Mul(EmpRecG.ErRate).Add(WsOtHours.Mul(EmpRecG.ErRate).Mul(onePointFive))
	// COMPUTE ROUNDED
	WsGross = grossCalc.Round(2)
	WsGross = storeDecimal(WsGross, 2, 7)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeDecimal(WsDeptTotal, 2, 9)
	WsDeptCount++
	// high order drop for count PIC 9(3)
	if WsDeptCount >= 1000 {
		WsDeptCount = WsDeptCount % 1000
	}
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimal(WsGrandTotal, 2, 11)
	WsGrandCount++
	if WsGrandCount >= 100000 {
		WsGrandCount = WsGrandCount % 100000
	}

	WsHoursEd = formatEdited(EmpRecG.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecG.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")

	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED.
	fmt.Printf("%s %s %s %s %s\n", EmpRecG.ErId, EmpRecG.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "  DEPT " WS-PREV-DEPT " EMPLOYEES: " WS-DEPT-COUNT " TOTAL: " WS-DEPT-ED
	countStr := formatPIC9(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.New(0, 0)
	WsDeptCount = 0
}

func GRAND_PARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatPIC9(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func main() {
	// ensure bufio import used
	_ = bufio.NewReader
	initVars()
	MAIN_PARA()
}
